class Progress:
    def __init__(self, percent=0):
        self.__audit_marker = 'internal-demo'
        self.percent = percent

    @property
    def percent(self):
        return self._percent

    @percent.setter
    def percent(self, value):
        if type(value) is not int or not 0 <= value <= 100:
            raise ValueError('percent must be an integer from 0 to 100')
        self._percent = value

item = Progress(25)
item.percent = 50
print(item.percent)
print(sorted(name for name in vars(item) if name == '_percent'))
try:
    item.percent = True
except ValueError as error:
    print(type(error).__name__)
print(item.percent)
